from pathlib import Path
import re

path = Path('/home/ubuntu/eurotruck-clone/client/src/pages/Inventory.tsx')
text = path.read_text()
pattern = re.compile(r': <div className="inventory-list">.*?</div>}</aside>', re.S)
replacement = r''': countedGroups.length === 0 ? <div className="inventory-empty"><PackageSearch size={28} /><p>Aún no hay artículos contados.</p></div> : <div className="inventory-location-groups">{countedGroups.map((group, groupIndex) => <section className={`inventory-location-group inventory-location-group--${groupIndex % 4}`} key={`${group.tramo}::${group.gondola}`}><header className="inventory-location-group-header"><div><span className="orders-eyebrow">UBICACIÓN {String(groupIndex + 1).padStart(2, "0")}</span><h3>{group.tramo} / {group.gondola}</h3></div><strong>{group.items.length} artículo{group.items.length === 1 ? "" : "s"}</strong></header><div className="inventory-location-group-list">{group.items.map(item => { const expanded = expandedInventoryId === item.id; const history = (historyQuery.data as InventoryScanRow[] | undefined) || []; const countedProduct = allProducts.find(product => product.id === item.productId); return <article className={`inventory-row is-counted${item.totalQuantity <= lowStockThreshold ? " is-low-stock" : ""}`} key={item.id} role="button" tabIndex={0} onClick={() => countedProduct && selectProduct(countedProduct)} onKeyDown={event => { if ((event.key === "Enter" || event.key === " ") && countedProduct) { event.preventDefault(); selectProduct(countedProduct); } }}><div className="inventory-row-copy"><strong>{item.sku}</strong>{getGtinsForSku(item.sku, gtinMap).length ? <em>GTIN {getGtinsForSku(item.sku, gtinMap).join(" · ")}</em> : <em className="inventory-gtin-missing">GTIN no registrado</em>}<h3>{item.name}</h3><small>{item.lastTramo || "—"} · {item.lastGondola || "—"} · {item.scanCount || 0} lecturas</small><button type="button" className="inventory-row-sale-button" onClick={event => { event.stopPropagation(); setSaleCode(item.sku); setSaleQuantity("1"); setSaleConfirmSku(item.sku); setSaleConfirmKey(""); setSaleConfirmError(""); }}>Eliminar del inventario</button></div><div className="inventory-row-actions"><b>{item.totalQuantity}</b><button type="button" className="inventory-history-toggle" aria-expanded={expanded} onClick={event => { event.stopPropagation(); setExpandedInventoryId(expanded ? null : item.id); }}>{expanded ? "Ocultar historial" : `Ver historial (${item.scanCount || 0})`}</button></div>{expanded && <div className="inventory-history" aria-live="polite">{historyQuery.isLoading ? <small><LoaderCircle className="orders-spin" /> Cargando historial…</small> : history.length === 0 ? <small>No hay lecturas guardadas.</small> : history.map(scan => <div className="inventory-history-item" key={scan.id}><div><strong>{scan.tramo} / {scan.gondola}</strong><small>{formatInventoryScanDate(scan.createdAt)} · {scan.countedBy}</small></div><div className="inventory-history-actions"><b>+{scan.quantity}</b><button type="button" className="inventory-delete-scan" title="Eliminar esta lectura" aria-label={`Eliminar lectura del ${formatInventoryScanDate(scan.createdAt)}`} disabled={deleteScan.isPending} onClick={event => { event.stopPropagation(); if (window.confirm(`¿Eliminar esta lectura de ${item.sku} (${scan.tramo} / ${scan.gondola})? Se restará ${scan.quantity} unidad${scan.quantity === 1 ? "" : "es"}.`)) deleteScan.mutate({ scanId: scan.id }); }}><Trash2 size={15} /></button></div></div>)}</div>}</article>; })}</div></section>)}</div>}</aside>'''
new_text, count = pattern.subn(replacement, text, count=1)
if count != 1:
    raise SystemExit(f'No se encontró el bloque contado: {count}')
path.write_text(new_text)
print('Grouped inventory locations')
